fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // If the subarray would overflow the main array, it can't match.
    if start + sub.len() > main.len() {
        return false;
    }

    // Check element-wise equality.
    for i in 0..sub.len() {
        if main[start + i] != sub[i] {
            return false;
        }
    }

    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // The empty subarray always matches.
    if sub.is_empty() {
        return true;
    }

    // If sub is longer than main, it can't match.
    if sub.len() > main.len() {
        return false;
    }

    // Try every possible starting position.
    let max_start = main.len() - sub.len();
    for start in 0..=max_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }

    false
}

